const response = $('Call AI').first().json;

const VALID_MESSAGE_FOCUS = ['stat_lead', 'pain_point', 'solution', 'proof', 'education'];
const VALID_CREATIVE_HOOK = ['hero_stat', 'multi_stat', 'headline_lead', 'data_viz', 'process_flow'];

const raw = response.choices?.[0]?.message?.content;
if (!raw) throw new Error('No content from model: ' + JSON.stringify(response));

let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch(e) {
  throw new Error('Invalid JSON from model: ' + cleaned.substring(0, 200));
}

const messageFocus = (parsed.messageFocus || []).filter(v => VALID_MESSAGE_FOCUS.includes(v));
const creativeHook = (parsed.creativeHook || []).filter(v => VALID_CREATIVE_HOOK.includes(v));

return [{
  json: {
    messageFocus: messageFocus.length > 0 ? messageFocus : [VALID_MESSAGE_FOCUS[0]],
    creativeHook: creativeHook.length > 0 ? creativeHook : [VALID_CREATIVE_HOOK[0]]
  }
}];
